void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // ------------ just draw with pow  
    float time = abs(tan(iTime));
    float y = pow(uv.x,time);
    float naname = abs(y-uv.y);  
    float ss = smoothstep(0.02,0.0,naname);

    vec3 color = vec3(step(0.5,y));

    // ------------ naname pow and smth
    vec3 addsscolor = ss * vec3(0,0,y) + ss * vec3(0,1.0 - y,0) + (1.0 - ss) * color;



    // Output to screen
    fragColor = vec4(addsscolor,1.0);
}
